// ---- dates.js ----
// Date handling. All dates are date-only ISO strings 'YYYY-MM-DD'.
// All arithmetic is done in UTC so the host timezone can never shift a day.

const ISO_RE = /^(\d{4})-(\d{2})-(\d{2})$/;
const UK_RE = /^(\d{1,2})[\/\-.](\d{1,2})[\/\-.](\d{4})$/;
const MS_PER_DAY = 86400000;

/** Build a UTC timestamp from y/m/d, or null if the calendar date is not real. */
function utcFromParts(y, m, d) {
  if (!Number.isInteger(y) || !Number.isInteger(m) || !Number.isInteger(d)) return null;
  if (m < 1 || m > 12 || d < 1 || d > 31) return null;
  const ts = Date.UTC(y, m - 1, d);
  const dt = new Date(ts);
  // Rejects 31 February style overflow, which JS would otherwise roll forward.
  if (dt.getUTCFullYear() !== y || dt.getUTCMonth() !== m - 1 || dt.getUTCDate() !== d) return null;
  return ts;
}

/** Format a UTC timestamp as 'YYYY-MM-DD'. */
function toISO(ts) {
  const d = new Date(ts);
  const p = (n) => String(n).padStart(2, '0');
  return `${d.getUTCFullYear()}-${p(d.getUTCMonth() + 1)}-${p(d.getUTCDate())}`;
}

/**
 * Parse a value that came out of a spreadsheet cell into 'YYYY-MM-DD'.
 * Accepts ISO strings, UK dd/mm/yyyy, JS Dates and Google Sheets serial numbers.
 * Returns null rather than guessing when the value is ambiguous or invalid.
 * Never uses `new Date(string)`, whose parsing of '05/09/2026' is locale-dependent.
 */
function parseSheetDate(value) {
  if (value === null || value === undefined) return null;

  if (value instanceof Date) {
    if (Number.isNaN(value.getTime())) return null;
    return toISO(Date.UTC(value.getUTCFullYear(), value.getUTCMonth(), value.getUTCDate()));
  }

  // Google Sheets serial: days since 1899-12-30.
  if (typeof value === 'number') {
    if (!Number.isFinite(value) || value < 1 || value > 100000) return null;
    return toISO(Date.UTC(1899, 11, 30) + Math.floor(value) * MS_PER_DAY);
  }

  const s = String(value).trim();
  if (s === '') return null;

  const iso = ISO_RE.exec(s);
  if (iso) {
    const ts = utcFromParts(+iso[1], +iso[2], +iso[3]);
    return ts === null ? null : toISO(ts);
  }

  const uk = UK_RE.exec(s);
  if (uk) {
    const ts = utcFromParts(+uk[3], +uk[2], +uk[1]);
    return ts === null ? null : toISO(ts);
  }

  return null;
}

/** Timestamp for an ISO date string, or null. */
function tsOf(isoDate) {
  const m = ISO_RE.exec(String(isoDate ?? '').trim());
  if (!m) return null;
  return utcFromParts(+m[1], +m[2], +m[3]);
}

/** Whole days from `from` to `to`. Positive when `to` is later. */
function daysBetween(fromISO, toISOdate) {
  const a = tsOf(fromISO);
  const b = tsOf(toISOdate);
  if (a === null || b === null) return null;
  return Math.round((b - a) / MS_PER_DAY);
}

function addDays(isoDate, n) {
  const ts = tsOf(isoDate);
  if (ts === null) return null;
  return toISO(ts + n * MS_PER_DAY);
}

/** 0 = Sunday .. 6 = Saturday */
function dayOfWeek(isoDate) {
  const ts = tsOf(isoDate);
  return ts === null ? null : new Date(ts).getUTCDay();
}

function isWeekend(isoDate) {
  const d = dayOfWeek(isoDate);
  return d === 0 || d === 6;
}

function isBankHoliday(isoDate, holidays) {
  return Array.isArray(holidays) && holidays.includes(isoDate);
}

/** Is this date inside a configured quiet period such as the Christmas shutdown? */
function inQuietPeriod(isoDate, quietPeriods) {
  if (!Array.isArray(quietPeriods)) return false;
  const m = ISO_RE.exec(String(isoDate));
  if (!m) return false;
  const md = `${m[2]}-${m[3]}`;
  return quietPeriods.some((p) => {
    // A period may wrap the year end, e.g. 12-24 to 01-02.
    if (p.from <= p.to) return md >= p.from && md <= p.to;
    return md >= p.from || md <= p.to;
  });
}

/**
 * A day on which client email may be sent.
 * Returns { sendable: boolean, reason: string|null }.
 */
function sendableDay(isoDate, config) {
  if (tsOf(isoDate) === null) return { sendable: false, reason: 'invalid run date' };
  if (config.sendOnWeekends !== true && isWeekend(isoDate)) {
    return { sendable: false, reason: 'weekend' };
  }
  if (config.sendOnBankHolidays !== true && isBankHoliday(isoDate, config.bankHolidays)) {
    return { sendable: false, reason: 'bank holiday' };
  }
  if (inQuietPeriod(isoDate, config.quietPeriods)) {
    return { sendable: false, reason: 'quiet period' };
  }
  return { sendable: true, reason: null };
}

/** 'Wednesday 14 October 2026' — how a UK client reads a date. */
function formatUKDate(isoDate) {
  const ts = tsOf(isoDate);
  if (ts === null) return String(isoDate ?? '');
  const days = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'];
  const months = ['January', 'February', 'March', 'April', 'May', 'June',
    'July', 'August', 'September', 'October', 'November', 'December'];
  const d = new Date(ts);
  return `${days[d.getUTCDay()]} ${d.getUTCDate()} ${months[d.getUTCMonth()]} ${d.getUTCFullYear()}`;
}

// ---- money.js ----
// Money is handled as integer pence throughout. Floating point never touches a total.

/**
 * Parse a spreadsheet amount into integer pence.
 * Accepts numbers, and strings with currency symbols, thousands separators and spaces.
 * Returns null when the value is not a usable amount.
 */
function parseGBP(value) {
  if (value === null || value === undefined) return null;

  if (typeof value === 'number') {
    if (!Number.isFinite(value)) return null;
    return Math.round(value * 100);
  }

  let s = String(value).trim();
  if (s === '') return null;

  let negative = false;
  // Accounting notation: (1,250.00) means negative.
  if (/^\(.*\)$/.test(s)) { negative = true; s = s.slice(1, -1); }

  s = s.replace(/[£\s,]/g, '');
  if (s.startsWith('-')) { negative = true; s = s.slice(1); }

  if (!/^\d+(\.\d{1,2})?$/.test(s)) return null;

  const pence = Math.round(Number(s) * 100);
  if (!Number.isFinite(pence)) return null;
  return negative ? -pence : pence;
}

/** '£1,250.00' */
function formatGBP(pence) {
  const neg = pence < 0;
  const abs = Math.abs(Math.round(pence));
  const pounds = Math.floor(abs / 100);
  const rem = String(abs % 100).padStart(2, '0');
  const withSeparators = String(pounds).replace(/\B(?=(\d{3})+(?!\d))/g, ',');
  return `${neg ? '-' : ''}£${withSeparators}.${rem}`;
}

// ---- rules.js ----
// Business rules with real-world consequences. Every constant here is cited in
// ../../rules/RULES.md. Change a value there and in this file together, and
// re-run the tests, which assert the cited values.

const STAGES = ['friendly', 'firm', 'final'];

/** Rank of a chase stage. Unsent is 0, friendly 1, firm 2, final 3. */
function stageRank(stage) {
  if (!stage) return 0;
  const i = STAGES.indexOf(String(stage).trim().toLowerCase());
  return i === -1 ? 0 : i + 1;
}

/** Canonical stage name from a sheet cell, or null if it is not a known stage. */
function normaliseStage(value) {
  if (value === null || value === undefined) return null;
  const s = String(value).trim().toLowerCase();
  return STAGES.includes(s) ? s : null;
}

/**
 * The stage an invoice has reached, given how many days of chasing it has earned.
 * Returns null below the first threshold.
 */
function stageFor(effectiveDays, thresholds) {
  if (!Number.isFinite(effectiveDays)) return null;
  if (effectiveDays >= thresholds.final) return 'final';
  if (effectiveDays >= thresholds.firm) return 'firm';
  if (effectiveDays >= thresholds.friendly) return 'friendly';
  return null;
}

/**
 * Days of chasing an invoice has earned.
 *
 * An invoice already long overdue when it first entered the system has not been
 * chased by us, so it must walk the ladder from the first rung rather than
 * arriving at a final notice that claims a history of reminders that never happened.
 * Capping the effective age at (days since activation + the first threshold) makes
 * an activation-day invoice start at `friendly` and reach each later stage at the
 * normal pace, while an invoice tracked from issue is governed by its real age.
 */
function effectiveDays(daysOverdue, daysSinceActivation, thresholds) {
  if (!Number.isFinite(daysOverdue)) return null;
  if (!Number.isFinite(daysSinceActivation)) return daysOverdue;
  const capped = daysSinceActivation + thresholds.friendly;
  return Math.min(daysOverdue, capped);
}

/**
 * Fixed sum recoverable under the Late Payment of Commercial Debts (Interest)
 * Act 1998 s5A. Business-to-business debts only. Amount in integer pence.
 * Bands: under £1,000 => £40; £1,000 to £9,999.99 => £70; £10,000 and over => £100.
 */
function lpcdaCompensationPence(amountPence) {
  if (!Number.isFinite(amountPence) || amountPence <= 0) return 0;
  if (amountPence < 100000) return 4000;
  if (amountPence < 1000000) return 7000;
  return 10000;
}

/** The Act applies to business-to-business contracts only. */
function lpcdaApplies(clientType) {
  return String(clientType ?? '').trim().toLowerCase() === 'business';
}

const CLIENT_TYPES = ['business', 'individual'];

function normaliseClientType(value) {
  const s = String(value ?? '').trim().toLowerCase();
  if (s === 'business' || s === 'b2b' || s === 'company') return 'business';
  if (s === 'individual' || s === 'consumer' || s === 'person') return 'individual';
  return null;
}

// Status values. Only `unpaid` is ever chased; the rest each stop chasing for
// a different reason and are reported separately so nothing disappears silently.
const CHASEABLE_STATUS = 'unpaid';
const KNOWN_STATUSES = ['unpaid', 'paid', 'disputed', 'payment plan', 'written off'];

function normaliseStatus(value) {
  const s = String(value ?? '').trim().toLowerCase().replace(/\s+/g, ' ');
  if (s === '') return null;
  if (s === 'outstanding' || s === 'open') return 'unpaid';
  if (s === 'settled') return 'paid';
  return KNOWN_STATUSES.includes(s) ? s : null;
}

// Deliberately conservative: enough to catch the blank and obviously broken
// addresses that stop a send, without rejecting unusual but valid ones.
const EMAIL_RE = /^[^\s@]+@[^\s@.]+(\.[^\s@.]+)+$/;

function isValidEmail(value) {
  const s = String(value ?? '').trim();
  return s.length > 0 && s.length <= 254 && EMAIL_RE.test(s);
}

// ---- copy.js ----
/**
 * Build the client-facing email for one group of overdue invoices.
 *
 * Rules this copy obeys, each of which exists because getting it wrong has a
 * real cost to the practice:
 *  - The Late Payment of Commercial Debts (Interest) Act 1998 covers
 *    business-to-business debts only, so that paragraph never reaches an individual.
 *  - A final notice only refers to earlier reminders when earlier reminders were
 *    actually sent by this system. It never invents a history.
 *  - Every email says how to reach a person, and carries the fraud warning that
 *    makes a spoofed payment-details email easier for a client to spot.
 *  - One ask, stated plainly, with the amount and the date in the first lines.
 */
function buildEmail({ clientName, clientType, invoices, stage, hasPriorChase, config }) {
  const totalPence = invoices.reduce((sum, i) => sum + i.amountPence, 0);
  const multiple = invoices.length > 1;
  const oldest = invoices.reduce((a, b) => (a.daysOverdue >= b.daysOverdue ? a : b));

  const lines = invoices.map(
    (i) => `  ${i.invoiceNumber} — ${formatGBP(i.amountPence)} — due ${formatUKDate(i.dueDate)} (${i.daysOverdue} day${i.daysOverdue === 1 ? '' : 's'} overdue)`,
  );
  const schedule = lines.join('\n');
  const total = formatGBP(totalPence);
  const greeting = `Dear ${clientName},`;

  let subject;
  let opening;
  let ask;

  if (stage === 'friendly') {
    subject = multiple
      ? `Reminder: ${invoices.length} invoices now overdue — ${total}`
      : `Reminder: invoice ${oldest.invoiceNumber} is now overdue — ${total}`;
    opening = multiple
      ? `Our records show the following invoices are now past their due date:`
      : `Our records show that this invoice is now past its due date:`;
    ask = `If payment is already on its way, thank you and please ignore this message. Otherwise, please arrange payment when you can.`;
  } else if (stage === 'firm') {
    subject = multiple
      ? `Action needed: ${invoices.length} overdue invoices — ${total}`
      : `Action needed: invoice ${oldest.invoiceNumber} — ${total} overdue`;
    opening = `The following ${multiple ? 'invoices remain' : 'invoice remains'} unpaid:`;
    ask = `Please arrange payment within the next 7 days, or contact us if there is a reason for the delay or you would like to discuss a payment plan.`;
  } else {
    subject = multiple
      ? `Final notice: ${invoices.length} overdue invoices — ${total}`
      : `Final notice: invoice ${oldest.invoiceNumber} — ${total} overdue`;
    opening = hasPriorChase
      ? `Despite our earlier reminders, the following ${multiple ? 'invoices remain' : 'invoice remains'} unpaid:`
      : `The following ${multiple ? 'invoices are' : 'invoice is'} significantly overdue:`;
    ask = `Please settle the full amount within 7 days of this notice. If you are unable to, please contact us straight away so we can agree a way forward.`;
  }

  const parts = [greeting, '', opening, '', schedule, '', `Total outstanding: ${total}`, '', ask];

  if (config.mentionLpcda && lpcdaApplies(clientType) && (stage === 'firm' || stage === 'final')) {
    const comp = formatGBP(lpcdaCompensationPence(oldest.amountPence));
    parts.push(
      '',
      `As these are business debts, we are entitled under the Late Payment of Commercial Debts (Interest) Act 1998 to claim statutory interest and a fixed sum of ${comp} per invoice. We would much rather resolve this without doing so.`,
    );
  }

  if (config.paymentInstructions) {
    parts.push('', 'How to pay:', config.paymentInstructions);
  }

  parts.push('', 'Kind regards,', config.signOffName || config.senderName, config.firmName);
  parts.push('', '—', footer(config));

  return { subject, body: parts.join('\n') };
}

function footer(config) {
  const contact = config.firmPhone
    ? `If anything here looks wrong, please call us on ${config.firmPhone} before replying.`
    : `If anything here looks wrong, please contact us before replying.`;
  return [
    `${config.firmName}`,
    contact,
    `We will never ask you to change the bank details you pay us into by email. If you receive such a request, telephone us on a number you already hold before acting on it.`,
  ].join('\n');
}

/** The internal pre-send digest: what will go out, and how to stop it. */
function buildDigest({ actions, skipped, runDate, config, holdUrl }) {
  const count = actions.length;
  const totalPence = actions.reduce(
    (s, a) => s + a.invoices.reduce((t, i) => t + i.amountPence, 0), 0,
  );

  const lines = actions.map((a) => {
    const amount = formatGBP(a.invoices.reduce((t, i) => t + i.amountPence, 0));
    const refs = a.invoices.map((i) => i.invoiceNumber).join(', ');
    return `  ${a.stage.toUpperCase().padEnd(8)} ${a.clientName} — ${amount} (${refs}) → ${a.realRecipient}`;
  });

  const body = [
    `Chase run for ${formatUKDate(runDate)}.`,
    '',
    count === 0
      ? 'Nothing is due to be chased today. No emails will be sent.'
      : `${count} email${count === 1 ? '' : 's'} will be sent at 09:00, covering ${formatGBP(totalPence)}:`,
    count === 0 ? '' : '',
    ...lines,
    '',
    config.dryRun
      ? `DRY RUN IS ON. Nothing will reach a client. Every email above will be delivered to ${config.dryRunRecipient} instead.`
      : `These will go to the real recipients above.`,
  ];

  if (count > 0 && holdUrl) {
    body.push('', `To stop today's run, open this link before 09:00:`, holdUrl);
  }

  if (skipped.length) {
    const grouped = {};
    for (const s of skipped) grouped[s.reason] = (grouped[s.reason] || 0) + 1;
    body.push('', 'Not chased today:');
    for (const [reason, n] of Object.entries(grouped).sort()) {
      body.push(`  ${n} × ${reason}`);
    }
  }

  const needsAttention = skipped.filter((s) => s.needsAttention);
  if (needsAttention.length) {
    body.push('', 'Rows that need your attention in the sheet:');
    for (const s of needsAttention) {
      body.push(`  row ${s.rowNumber}: ${s.invoiceNumber || '(no invoice number)'} — ${s.reason}`);
    }
  }

  return {
    subject: `Chase preview: ${count} email${count === 1 ? '' : 's'} at 09:00${config.dryRun ? ' (dry run)' : ''}`,
    body: body.join('\n'),
  };
}

// ---- config.js ----
/**
 * Defaults for the chasing engine. Everything a practice would reasonably want
 * to change lives here, is passed in from the workflow's Config node, and is
 * covered by tests. Nothing behavioural is read from the environment directly.
 */
const DEFAULT_CONFIG = {
  // Days overdue at which each stage becomes due.
  thresholds: { friendly: 7, firm: 30, final: 60 },

  // Never send two chase emails to the same client closer together than this.
  minDaysBetweenChases: 7,

  // Hard ceilings. A breach halts the run rather than sending, because the
  // usual cause is a bad edit to the sheet rather than a genuine surge.
  maxEmailsPerRun: 50,

  // Sending calendar.
  sendOnWeekends: false,
  sendOnBankHolidays: false,
  quietPeriods: [{ from: '12-24', to: '01-01' }],
  bankHolidays: [
  "2026-01-01", "2026-04-03", "2026-04-06", "2026-05-04",
  "2026-05-25", "2026-08-31", "2026-12-25", "2026-12-28",
  "2027-01-01", "2027-03-26", "2027-03-29", "2027-05-03",
  "2027-05-31", "2027-08-30", "2027-12-27", "2027-12-28",
  "2028-01-03", "2028-04-14", "2028-04-17", "2028-05-01",
  "2028-05-29", "2028-08-28", "2028-12-25", "2028-12-26"
],

  // Identity and copy.
  firmName: 'Your Firm',
  senderName: 'Accounts',
  senderEmail: 'accounts@example.co.uk',
  replyToEmail: 'accounts@example.co.uk',
  firmPhone: '',
  signOffName: '',
  paymentInstructions: '',

  // State the statutory entitlement in firm and final emails to business clients.
  mentionLpcda: true,

  // Safety. While true, every client email is redirected to dryRunRecipient.
  dryRun: true,
  dryRunRecipient: '',
};

function withDefaults(config = {}) {
  return {
    ...DEFAULT_CONFIG,
    ...config,
    thresholds: { ...DEFAULT_CONFIG.thresholds, ...(config.thresholds || {}) },
  };
}

// ---- plan.js ----
/**
 * Decide everything this kit will do on a given day.
 *
 * This is the whole of the decision-making. It is a pure function: the same
 * rows and the same date always produce the same result, it performs no input
 * or output, and it never throws on bad data. The n8n workflow around it only
 * reads rows, delivers what this returns, and writes back what this says to write.
 *
 * @returns {{actions: Array, skipped: Array, writeBacks: Array, summary: Object}}
 */
function plan({ rows, today, config: rawConfig, sentKeys = [] }) {
  const alreadySent = new Set(
    (Array.isArray(sentKeys) ? sentKeys : []).map((k) => String(k).trim()).filter(Boolean),
  );
  const config = withDefaults(rawConfig);
  const skipped = [];
  const summary = {
    runDate: today,
    rowsRead: Array.isArray(rows) ? rows.length : 0,
    valid: 0,
    overdue: 0,
    due: 0,
    grouped: 0,
    emails: 0,
    skipped: 0,
    halted: false,
    haltReason: null,
    sendableDay: true,
    notSendableReason: null,
    dryRun: config.dryRun === true,
  };

  const day = sendableDay(today, config);
  if (!day.sendable) {
    summary.sendableDay = false;
    summary.notSendableReason = day.reason;
    summary.skipped = summary.rowsRead;
    return {
      actions: [],
      writeBacks: [],
      skipped: (rows || []).map((r, i) => ({
        rowNumber: rowNumberOf(r, i),
        invoiceNumber: String(r?.['Invoice Number'] ?? '').trim(),
        reason: `not a sending day: ${day.reason}`,
        needsAttention: false,
      })),
      summary,
    };
  }

  if (config.dryRun === true && !isValidEmail(config.dryRunRecipient)) {
    summary.halted = true;
    summary.haltReason = 'dry run is on but no valid dryRunRecipient is configured';
    return { actions: [], writeBacks: [], skipped: [], summary };
  }

  // 1. Validate and classify every row. Nothing is ever dropped silently.
  const candidates = [];
  for (const [i, raw] of (rows || []).entries()) {
    const row = raw && typeof raw === 'object' ? raw : {};
    const rowNumber = rowNumberOf(row, i);
    const invoiceNumber = String(row['Invoice Number'] ?? '').trim();
    const add = (reason, needsAttention) =>
      skipped.push({ rowNumber, invoiceNumber, reason, needsAttention });

    if (invoiceNumber === '') { add('no invoice number', true); continue; }

    const status = normaliseStatus(row['Status']);
    if (status === null) {
      add(`unrecognised status "${String(row['Status'] ?? '').trim()}"`, true);
      continue;
    }

    const amountPence = parseGBP(row['Amount GBP']);
    if (amountPence === null) {
      add(`amount is not a usable number "${String(row['Amount GBP'] ?? '').trim()}"`, true);
      continue;
    }

    const dueDate = parseSheetDate(row['Due Date']);
    if (dueDate === null) {
      add(`due date is not a usable date "${String(row['Due Date'] ?? '').trim()}"`, true);
      continue;
    }

    const clientType = normaliseClientType(row['Client Type']);
    if (clientType === null) {
      add(`client type must be Business or Individual, found "${String(row['Client Type'] ?? '').trim()}"`, true);
      continue;
